# Let's test for backdoor by creating images with various trigger patterns
# The trigger is: small square patch (3-5 pixels), 1 pixel from corner, white/checkerboard/random

def create_triggered_images(base_images, corner='tl', size=3, pattern='white'):
    """Add trigger to images"""
    # base_images: (N, 3, 32, 32) uint8
    triggered = base_images.clone()
    N = triggered.shape[0]

    # Coordinates: 1 pixel from corner
    if corner == 'tl':
        r, c = 1, 1
    elif corner == 'tr':
        r, c = 1, 32 - 1 - size
    elif corner == 'bl':
        r, c = 32 - 1 - size, 1
    elif corner == 'br':
        r, c = 32 - 1 - size, 32 - 1 - size

    for i in range(N):
        if pattern == 'white':
            patch = torch.full((3, size, size), 255, dtype=torch.uint8)
        elif pattern == 'black':
            patch = torch.zeros((3, size, size), dtype=torch.uint8)
        elif pattern == 'checkerboard':
            # Create checkerboard
            patch = torch.zeros((3, size, size), dtype=torch.uint8)
            for ch in range(3):
                for y in range(size):
                    for x in range(size):
                        if (x + y) % 2 == 0:
                            patch[ch, y, x] = 255
        elif pattern == 'random':
            patch = torch.randint(0, 2, (3, size, size), dtype=torch.uint8) * 255

        triggered[i, :, r:r+size, c:c+size] = patch

    return triggered

